<script setup lang="ts">
import {onMounted,reactive,ref,computed,watch} from 'vue'
import {useRouter} from 'vue-router'
import {useDemoStore} from '../stores/demo'
import {getGpuResources} from '../api/resources'
import {preflightTraining,launchTraining} from '../api/training'
const store=useDemoStore(),router=useRouter(),error=ref(''),busy=ref(false),report=ref<Record<string,any>|null>(null),limit=ref(0)
const form=reactive({name:'OpenPI 单卡验证',modelId:'',datasetId:'',entry:'scripts/train_pytorch.py',configName:'pi05_dexmimicgen',assets:'assets',assetId:'',weightMode:'base',checkpointName:'',gpuCount:1,steps:20,batchSize:1,workers:0,saveInterval:10,logInterval:1,learningRate:0.00005,precision:'bfloat16',seed:42,keepLast:0})
const models=computed(()=>store.models.filter(m=>m.source==='import')),datasets=computed(()=>store.datasets.filter(d=>d.source==='upload')),model=computed(()=>models.value.find(m=>m.id===form.modelId))
watch(()=>form.modelId,()=>{form.weightMode=model.value?.weightMode==='checkpoints'?'checkpoint':model.value?.weightMode==='none'?'scratch':'base';form.checkpointName=''})
watch(form,()=>report.value=null)
onMounted(async()=>{try{await Promise.all([store.syncImportedModels(),store.syncUploadedDatasets()]);form.modelId=models.value[0]?.id??'';form.datasetId=datasets.value[0]?.id??'';limit.value=(await getGpuResources()).count}catch(e){error.value=String(e)}})
async function submit(preflight:boolean){busy.value=true;error.value='';try{if(preflight)report.value=(await preflightTraining({...form})).report;else{const job=await launchTraining({...form});await router.push('/real-jobs/'+job.id)}}catch(e){error.value=e instanceof Error?e.message:'请求失败'}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">OPENPI / PYTORCH</div><h1>真实训练</h1><p>使用已导入项目与原 Python 环境执行真实进程，W&amp;B 默认关闭。</p></div><button class="button" @click="router.push('/training')">返回模拟训练</button></div><div class="info-note">先预检，再进行单卡少步验证。P800 必须具备可运行此入口的 PyTorch CUDA 兼容环境。队列一次运行一个任务，避免平台内资源争用；不会管理平台外的训练进程。</div><div v-if="error" class="form-error" role="alert">{{error}}</div><form @submit.prevent="submit(false)"><fieldset :disabled="busy" class="real-form"><div class="form-grid"><label>任务名称<input v-model="form.name" required/></label><label>已导入模型<select v-model="form.modelId" required><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>已导入数据集<select v-model="form.datasetId" required><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>PyTorch 训练入口<input v-model="form.entry" required/><small>需提供 train_loop(config)，默认使用已导入项目中的脚本。</small></label><label>OpenPI 配置名<input v-model="form.configName" required/></label><label>Assets 基础目录<input v-model="form.assets" required/><small>相对于项目目录；配置名和 asset_id 应与归一化统计数据匹配。</small></label><label>Asset ID（可选）<input v-model="form.assetId"/><small>留空沿用项目配置；切换数据集需核对统计量与相机、动作字段。</small></label><label>初始权重<select v-model="form.weightMode"><option v-if="model?.weightMode!=='checkpoints'&&model?.weightMode!=='none'" value="base">基础权重</option><option value="checkpoint">已导入 PyTorch Checkpoint 参数微调</option><option value="scratch">从零初始化（需配置支持）</option></select></label><label v-if="form.weightMode==='checkpoint'">Checkpoint<select v-model="form.checkpointName" required><option value="">请选择</option><option value="latest">已知步数最大的 PyTorch 版本</option><option v-for="cp in model?.importedCheckpoints" :key="cp.name" :value="cp.name" :disabled="cp.format!=='pytorch'||!cp.complete">{{cp.name}} · {{cp.format}}</option></select></label><label>GPU 数量<select v-model.number="form.gpuCount"><option v-for="n in limit" :key="n" :value="n">{{n}}</option></select></label><label>总训练步数<input v-model.number="form.steps" type="number" min="1" required/></label><label>全局 Batch Size<input v-model.number="form.batchSize" type="number" min="1" required/></label><label>数据加载进程数<input v-model.number="form.workers" type="number" min="0" max="128"/></label><label>峰值 Learning Rate<input v-model.number="form.learningRate" type="number" min="0.00000001" step="any" required/></label><label>精度<select v-model="form.precision"><option>bfloat16</option><option>float32</option></select></label><label>随机种子<input v-model.number="form.seed" type="number" min="0"/></label><label>日志间隔<input v-model.number="form.logInterval" type="number" min="1"/></label><label>Checkpoint 保存间隔<input v-model.number="form.saveInterval" type="number" min="1" :max="form.steps"/></label></div><p class="info-note">使用项目配置的 AdamW 与学习率调度，仅覆盖峰值学习率。输出保存到服务端 managed-training 下的独立任务目录；已有权重不会被覆盖。当前保留所有真实 Checkpoints。</p><div class="form-actions"><button type="button" class="button" :disabled="busy||!form.modelId||!form.datasetId||!limit" @click="submit(true)">{{busy?'处理中…':'环境与设备预检'}}</button><button class="button primary" :disabled="busy||!form.modelId||!form.datasetId||!limit">创建真实任务并排队</button></div></fieldset></form><section v-if="report" class="panel content-panel"><h2>预检通过</h2><pre class="command-preview">{{JSON.stringify(report,null,2)}}</pre><p>任务出队启动前会再次预检。首次 JIT、模型加载和数据读取仍可能失败，结果以任务日志为准。</p></section></template>
<style scoped>.real-form{border:0;padding:0;margin-top:24px;max-width:900px}.real-form .form-grid{grid-template-columns:1fr}.real-form:disabled{opacity:.7}</style>
